import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.DotktHmf.js";const h=JSON.parse('{"title":"URL parameters","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/guide/url-parameters.html"}],["meta",{"property":"og:title","content":"URL parameters | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/guide/url-parameters.html"}],["meta",{"name":"twitter:title","content":"URL parameters | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"guide/url-parameters.md","filePath":"guide/url-parameters.md"}'),r={name:"guide/url-parameters.md"};function c(s,e,i,n,l,p){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="url-parameters" tabindex="-1">URL parameters <a class="header-anchor" href="#url-parameters" aria-label="Permalink to &quot;URL parameters&quot;">​</a></h1><p>The demo viewer reads its state from the URL; <strong>Share</strong> (top right) copies the current view as a link.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Values</th><th>Description</th></tr></thead><tbody><tr><td><code>dataset</code></td><td>URL</td><td>OME-Zarr or sharded binary dataset</td></tr><tr><td><code>sourceChannels</code></td><td>zero-based indices, e.g. <code>5,1</code></td><td>1–4 source channels in display order (default: the first four)</td></tr><tr><td><code>timepoint</code></td><td>zero-based index</td><td>Timepoint (default 0)</td></tr><tr><td><code>mode</code></td><td><code>dvr</code>, <code>mip</code>, <code>iso</code>, <code>lod</code>, <code>slice</code></td><td>Render mode</td></tr><tr><td><code>wc</code>, <code>ww</code></td><td>0–1</td><td>Window centre and width</td></tr><tr><td><code>iso</code></td><td>0–1</td><td>Isosurface threshold</td></tr><tr><td><code>density</code></td><td>0.1–10</td><td>DVR opacity scale</td></tr><tr><td><code>shade</code></td><td>0–1</td><td>DVR gradient shading (default 0)</td></tr><tr><td><code>boundary</code></td><td>0–1</td><td>DVR boundary emphasis: opacity follows gradient magnitude (default 0)</td></tr><tr><td><code>tf</code></td><td><code>grayscale</code>, <code>grayscale-inverted</code>, <code>coolwarm</code>, <code>hot</code>, <code>cool</code>, <code>viridis</code>, <code>plasma</code>, <code>seismic</code></td><td>Transfer function preset</td></tr><tr><td><code>tfpts</code></td><td>x,y pairs, e.g. <code>0,0,0.5,0.8,1,1</code></td><td>Transfer function opacity points</td></tr><tr><td><code>up</code></td><td><code>x</code>, <code>y</code>, <code>z</code>, <code>-x</code>, <code>-y</code>, <code>-z</code></td><td>Camera up axis</td></tr><tr><td><code>cam</code></td><td><code>rx,ry,dist,tx,ty,tz</code></td><td>Camera rotation, distance and target</td></tr><tr><td><code>scale</code></td><td>0.25–1</td><td>Render resolution scale</td></tr><tr><td><code>sse</code></td><td>pixels</td><td>LOD screen-space error threshold (default 8; lower = sharper, more data)</td></tr><tr><td><code>pyramid</code></td><td><code>native</code>, <code>legacy</code></td><td>Level model. Default: native, falling back to legacy if the levels don&#39;t fit; setting it disables the fallback</td></tr><tr><td><code>clipMin</code>, <code>clipMax</code></td><td>x,y,z (0–1)</td><td>Clip box</td></tr><tr><td><code>slices</code></td><td>x,y,z (0–1)</td><td>Slice positions (<code>slice</code> mode)</td></tr><tr><td><code>sliceVis</code></td><td>0–7</td><td>Visible slice planes as a bitmask (X = 1, Y = 2, Z = 4; default 7)</td></tr><tr><td><code>wireframe</code>, <code>axis</code></td><td><code>1</code></td><td>Bounding box and axis overlays</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>?dataset=https://example.com/scan.ome.zarr&amp;mode=mip&amp;wc=0.2&amp;ww=0.3&amp;tf=coolwarm</span></span></code></pre></div><p>The multichannel viewer uses <code>channels</code> and <code>slice</code> instead of the single-channel display parameters: see <a href="/rendering/multichannel.html#multichannel-demo">Multichannel demo</a>.</p><h2 id="diagnostics-and-experiments" tabindex="-1">Diagnostics and experiments <a class="header-anchor" href="#diagnostics-and-experiments" aria-label="Permalink to &quot;Diagnostics and experiments&quot;">​</a></h2><p>Not included in share links.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>debug=1</code></td><td>Opens the stats panel (also <code>D</code>)</td></tr><tr><td><code>bench=1</code></td><td>Once streaming and accumulation have converged, logs a report (timings, bytes, bricks) and sets <code>window.__KILN_BENCH_RESULT</code>. Options: <code>benchLabel</code>, <code>benchTimeout</code> (ms, default 120000), <code>benchStable</code> (polls, default 8), <code>report=&lt;url&gt;</code> to POST the JSON</td></tr><tr><td><code>rayguide=0</code></td><td>Turns off <a href="/architecture/streaming.html#ray-guided-selection">ray-guided brick selection</a>, which is on by default</td></tr><tr><td><code>local=true</code></td><td>Set by the viewer after opening a local directory; reopens it on reload</td></tr></tbody></table>',8)])])}const u=t(r,[["render",c]]);export{h as __pageData,u as default};
